import { Controller, Get, Post, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const STATUSES = ['신청', '마감', '마감취소'];

const invalid = (message: string) =>
  new ApiError(422, 'OPENING_BALANCE_INVALID_INPUT', message);

function amountOf(value: unknown): string {
  const text = typeof value === 'number' ? String(value) : value;
  if (typeof text !== 'string' || !/^-?\d{1,16}(\.\d{1,2})?$/.test(text.trim())) {
    throw invalid('이월 금액은 숫자 형식으로 입력해 주세요.');
  }
  return text.trim();
}

function idOf(value: unknown): string {
  if (typeof value !== 'string' || !/^\d{1,18}$/.test(value)) {
    throw new ApiError(404, 'OPENING_BALANCE_NOT_FOUND', '이월내역을 찾을 수 없습니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr00605Controller {
  @Post('/opening-balances')
  @HttpCode(200)
  async createOpeningBalance(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const rawAccount = data['accountItemId'];
    const accountText = typeof rawAccount === 'number' ? String(rawAccount) : rawAccount;
    if (typeof accountText !== 'string' || !/^\d{1,18}$/.test(accountText)) {
      throw invalid('계정과목은 필수입니다.');
    }
    const amount = amountOf(data['carryoverAmount']);
    const rawYear = data['fiscalYear'];
    let fiscalYear: string | null = null;
    if (rawYear !== undefined && rawYear !== null && rawYear !== '') {
      const yearText = typeof rawYear === 'number' ? String(rawYear) : rawYear;
      if (typeof yearText !== 'string' || !/^\d{4}$/.test(yearText)) {
        throw invalid('회계연도 형식이 올바르지 않습니다.');
      }
      fiscalYear = yearText;
    }
    return transaction(async (db) => {
      const accounts = await db.query(
        'SELECT account_item_id FROM account_item WHERE account_item_id = CAST(:accountItemId AS bigint)',
        { accountItemId: accountText },
      );
      if (accounts.length === 0) {
        throw new ApiError(404, 'ACCOUNT_ITEM_NOT_FOUND', '계정과목을 찾을 수 없습니다.');
      }
      if (fiscalYear !== null) {
        const dup = await db.query(
          'SELECT opening_balance_id FROM opening_balance WHERE account_item_id = CAST(:accountItemId AS bigint) AND fiscal_year = CAST(:fiscalYear AS integer)',
          { accountItemId: accountText, fiscalYear },
        );
        if (dup.length > 0) {
          throw invalid('같은 계정과목·회계연도의 이월내역이 이미 있습니다.');
        }
      }
      const rows = await db.query(
        "INSERT INTO opening_balance (account_item_id, carryover_amount, status, fiscal_year, created_at, updated_at) VALUES (CAST(:accountItemId AS bigint), CAST(:amount AS numeric), '신청', CAST(:fiscalYear AS integer), now(), now()) RETURNING opening_balance_id AS "openingBalanceId", status AS "status"",
        { accountItemId: accountText, amount, fiscalYear },
      );
      return rows[0];
    });
  }

  @Patch('/opening-balances/:openingBalanceId')
  async updateOpeningBalance(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req.params['openingBalanceId']);
    const data = checks.inputOf(req.body);
    const amount = amountOf(data['carryoverAmount']);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status AS "status" FROM opening_balance WHERE opening_balance_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'OPENING_BALANCE_NOT_FOUND', '이월내역을 찾을 수 없습니다.');
      }
      if (rows[0].status === '마감') {
        throw new ApiError(409, 'OPENING_BALANCE_CLOSED', '마감된 이월내역은 수정할 수 없습니다. 마감취소 후 수정해 주세요.');
      }
      await db.execute(
        'UPDATE opening_balance SET carryover_amount = CAST(:amount AS numeric), updated_at = now() WHERE opening_balance_id = CAST(:id AS bigint)',
        { id, amount },
      );
      return { openingBalanceId: Number(id) };
    });
  }

  @Post('/opening-balances/:openingBalanceId/close')
  @HttpCode(200)
  async closeOpeningBalance(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req.params['openingBalanceId']);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status AS "status" FROM opening_balance WHERE opening_balance_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'OPENING_BALANCE_NOT_FOUND', '이월내역을 찾을 수 없습니다.');
      }
      if (rows[0].status === '마감') {
        throw new ApiError(409, 'OPENING_BALANCE_ALREADY_CLOSED', '이미 마감된 이월내역입니다.');
      }
      await db.execute(
        "UPDATE opening_balance SET status = '마감', updated_at = now() WHERE opening_balance_id = CAST(:id AS bigint)",
        { id },
      );
      return { status: '마감' };
    });
  }

  @Post('/opening-balances/:openingBalanceId/cancel-close')
  @HttpCode(200)
  async cancelCloseOpeningBalance(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req.params['openingBalanceId']);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status AS "status" FROM opening_balance WHERE opening_balance_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'OPENING_BALANCE_NOT_FOUND', '이월내역을 찾을 수 없습니다.');
      }
      if (rows[0].status !== '마감') {
        throw new ApiError(409, 'OPENING_BALANCE_NOT_CLOSED', '마감 상태가 아닌 이월내역입니다.');
      }
      await db.execute(
        "UPDATE opening_balance SET status = '마감취소', updated_at = now() WHERE opening_balance_id = CAST(:id AS bigint)",
        { id },
      );
      return { status: '마감취소' };
    });
  }

  @Get('/opening-balances')
  async listOpeningBalances(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const pageText = query['page'] === undefined || query['page'] === '' ? '0' : String(query['page']);
    const sizeText = query['size'] === undefined || query['size'] === '' ? '20' : String(query['size']);
    if (!/^\d{1,9}$/.test(pageText) || !/^\d{1,9}$/.test(sizeText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'page와 size는 숫자여야 합니다.');
    }
    const page = Number(pageText);
    const size = Math.min(Math.max(Number(sizeText), 1), 200);
    const accountRaw = query['accountItemId'];
    let accountItemId: string | null = null;
    if (accountRaw !== undefined && accountRaw !== '') {
      if (!/^\d{1,18}$/.test(String(accountRaw))) {
        throw new ApiError(400, 'VALIDATION_FAILED', '계정과목 형식이 올바르지 않습니다.');
      }
      accountItemId = String(accountRaw);
    }
    const statusRaw = query['status'];
    let status: string | null = null;
    if (statusRaw !== undefined && statusRaw !== '') {
      if (!STATUSES.includes(String(statusRaw))) {
        throw new ApiError(400, 'VALIDATION_FAILED', '마감 처리 상태 값이 올바르지 않습니다.');
      }
      status = String(statusRaw);
    }
    return transaction(async (db) => {
      const where =
        'WHERE (CAST(:accountItemId AS bigint) IS NULL OR account_item_id = CAST(:accountItemId AS bigint)) AND (CAST(:status AS varchar) IS NULL OR status = CAST(:status AS varchar))';
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM opening_balance ' + where,
        { accountItemId, status },
      );
      const items = await db.query(
        'SELECT opening_balance_id AS "openingBalanceId", account_item_id AS "accountItemId", carryover_amount AS "carryoverAmount", status AS "status", fiscal_year AS "fiscalYear" FROM opening_balance ' +
          where +
          ' ORDER BY opening_balance_id DESC LIMIT :size OFFSET :offset',
        { accountItemId, status, size, offset: page * size },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }
}

