import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  Pager,
  Pairs,
  RefName,
  Select,
  Tiles,
  call,
  useData,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;
const STATUS_OPTIONS: [string, string][] = [
  ['신청', '신청'],
  ['마감', '마감'],
  ['마감취소', '마감취소'],
];

type DrawerState =
  | { kind: 'create' }
  | { kind: 'detail'; row: Row }
  | { kind: 'edit'; row: Row }
  | null;

export default function FnSfr00605Page({ role, notify }: PageProps) {
  const [draftAccount, setDraftAccount] = useState<number | string>('');
  const [draftStatus, setDraftStatus] = useState('');
  const [applied, setApplied] = useState({ accountItemId: '' as number | string, status: '' });
  const [pageNo, setPageNo] = useState(0);
  const [drawer, setDrawer] = useState<DrawerState>(null);
  const [accountItemId, setAccountItemId] = useState<number | string>('');
  const [amount, setAmount] = useState<number | string>('');
  const [fiscalYear, setFiscalYear] = useState<number | string>('');

  const list = useData<Page>(
    () =>
      call<Page>('GET', '/opening-balances', role, undefined, {
        accountItemId: applied.accountItemId,
        status: applied.status,
        page: pageNo,
        size: SIZE,
      }),
    [applied, pageNo],
  );
  const waiting = useData<Page>(
    () => call<Page>('GET', '/opening-balances', role, undefined, { status: '신청', page: 0, size: 1 }),
    [],
  );
  const closed = useData<Page>(
    () => call<Page>('GET', '/opening-balances', role, undefined, { status: '마감', page: 0, size: 1 }),
    [],
  );

  const refresh = () => {
    list.reload();
    waiting.reload();
    closed.reload();
  };

  const openCreate = () => {
    setAccountItemId('');
    setAmount('');
    setFiscalYear('');
    setDrawer({ kind: 'create' });
  };

  const openEdit = (row: Row) => {
    setAmount(row['carryoverAmount'] as number);
    setDrawer({ kind: 'edit', row });
  };

  const create = async () => {
    if (accountItemId === '' || amount === '') {
      throw new Error('계정과목과 이월 금액을 입력해 주세요.');
    }
    await call('POST', '/opening-balances', role, {
      accountItemId,
      carryoverAmount: amount,
      fiscalYear: fiscalYear === '' ? undefined : fiscalYear,
    });
    notify('이월내역을 등록했습니다.');
    setDrawer(null);
    refresh();
  };

  const update = async (row: Row) => {
    if (amount === '') {
      throw new Error('이월 금액을 입력해 주세요.');
    }
    await call('PATCH', '/opening-balances/' + String(row['openingBalanceId']), role, {
      carryoverAmount: amount,
    });
    notify('이월내역을 수정했습니다.');
    setDrawer(null);
    refresh();
  };

  const act = async (row: Row, action: 'close' | 'cancel-close', message: string) => {
    await call('POST', '/opening-balances/' + String(row['openingBalanceId']) + '/' + action, role, {});
    notify(message);
    setDrawer(null);
    refresh();
  };

  const rows = list.data ? list.data.items : [];
  const total = list.data ? list.data.total : 0;

  return (
    <div className='bento'>
      <section className='box span-4'>
        <h2>처리 대기</h2>
        <Tiles items={[['신청 상태', <Num value={waiting.data ? waiting.data.total : 0} />]]} />
      </section>
      <section className='box span-4'>
        <h2>마감 완료</h2>
        <Tiles items={[['마감 상태', <Num value={closed.data ? closed.data.total : 0} />]]} />
      </section>
      <section className='box span-4'>
        <h2>전체 이월내역</h2>
        <Tiles items={[['조회 건수', <Num value={total} />]]} />
      </section>
      <section className='box span-12'>
        <h2>계정별 이월내역</h2>
        <Filters
          onSearch={() => {
            setPageNo(0);
            setApplied({ accountItemId: draftAccount, status: draftStatus });
          }}
          onReset={() => {
            setDraftAccount('');
            setDraftStatus('');
            setPageNo(0);
            setApplied({ accountItemId: '', status: '' });
          }}
        >
          <Field label='계정과목'>
            <LookupSelect table='account_item' role={role} value={draftAccount} onChange={setDraftAccount} />
          </Field>
          <Field label='마감 처리 상태'>
            <Select value={draftStatus} onChange={setDraftStatus} options={STATUS_OPTIONS} />
          </Field>
        </Filters>
        <Band total={total}>
          <button type='button' onClick={openCreate}>이월 등록</button>
        </Band>
        {list.error ? <p>{list.error}</p> : null}
        <DataTable
          rows={rows}
          empty='이월내역이 없습니다.'
          onRowClick={(row) => setDrawer({ kind: 'detail', row })}
          columns={[
            { key: 'accountItemId', label: '계정과목', render: (r) => <RefName table='account_item' role={role} value={r['accountItemId']} /> },
            { key: 'fiscalYear', label: '회계연도' },
            { key: 'carryoverAmount', label: '이월 금액', render: (r) => <Num value={r['carryoverAmount']} /> },
            { key: 'status', label: '마감 처리 상태', render: (r) => <Badge value={r['status']} /> },
          ]}
        />
        <Pager page={pageNo} size={SIZE} total={total} onPage={setPageNo} />
      </section>

      {drawer && drawer.kind === 'create' ? (
        <Drawer title='이월 등록' onClose={() => setDrawer(null)}>
          <Form onSubmit={create} submit='등록'>
            <Field label='계정과목' required>
              <LookupSelect table='account_item' role={role} value={accountItemId} onChange={setAccountItemId} />
            </Field>
            <Field label='이월 금액' required>
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
            <Field label='회계연도'>
              <NumberInput value={fiscalYear} onChange={setFiscalYear} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {drawer && drawer.kind === 'detail' ? (
        <Drawer title='이월내역 상세' onClose={() => setDrawer(null)}>
          <Pairs
            items={[
              ['계정과목', <RefName table='account_item' role={role} value={drawer.row['accountItemId']} />],
              ['회계연도', String(drawer.row['fiscalYear'] ?? '')],
              ['이월 금액', <Num value={drawer.row['carryoverAmount']} />],
              ['마감 처리 상태', <Badge value={drawer.row['status']} />],
            ]}
          />
          {drawer.row['status'] !== '마감' ? (
            <>
              <button type='button' onClick={() => openEdit(drawer.row)}>수정</button>
              <Form onSubmit={() => act(drawer.row, 'close', '마감했습니다.')} submit='마감' />
            </>
          ) : (
            <Form
              danger
              onSubmit={() => act(drawer.row, 'cancel-close', '마감을 취소했습니다.')}
              submit='마감취소'
              note='마감된 이월내역은 마감취소 후에만 수정할 수 있습니다.'
            />
          )}
        </Drawer>
      ) : null}

      {drawer && drawer.kind === 'edit' ? (
        <Drawer title='이월내역 수정' onClose={() => setDrawer(null)}>
          <Form onSubmit={() => update(drawer.row)} submit='수정'>
            <Field label='계정과목'>
              <RefName table='account_item' role={role} value={drawer.row['accountItemId']} />
            </Field>
            <Field label='이월 금액' required>
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
